/* eslint-disable no-undef */
/* eslint-disable no-console */
import React, { useState, useEffect } from "react";

export default function SafetyCheck() {
  const [latitude, setLatitude] = useState("");
  const [longitude, setLongitude] = useState("");
  const [result, setResult] = useState("");
  const [loading, setLoading] = useState(false);
  const [autoFetched, setAutoFetched] = useState(false);

  // 🌍 Automatically fetch user location on load
  useEffect(() => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (position) => {
          setLatitude(position.coords.latitude.toFixed(4));
          setLongitude(position.coords.longitude.toFixed(4));
          setAutoFetched(true);
        },
        (error) => {
          console.error("Auto location fetch failed:", error);
        }
      );
    }
  }, []);

  // ✅ Check safety with backend
  const handleCheckSafety = async () => {
    if (!latitude || !longitude) {
      alert("Please allow location access first!");
      return;
    }

    try {
      setLoading(true);
      const response = await fetch("http://localhost:5000/api/safety/check", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          latitude: parseFloat(latitude),
          longitude: parseFloat(longitude),
        }),
      });

      if (!response.ok) throw new Error("Network response was not ok");

      const data = await response.json();
      setResult(data.message);
    } catch (error) {
      console.error("Error checking safety:", error);
      setResult("⚠️ Error checking safety");
    } finally {
      setLoading(false);
    }
  };

  // 🎨 UI
  return (
    <div
      style={{
        height: "100vh",
        background: "linear-gradient(135deg, #ffcc70, #ff8c00, #ff5f6d)",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        fontFamily: "'Poppins', sans-serif",
        transition: "all 0.5s ease-in-out",
      }}
    >
      <div
        style={{
          backgroundColor: "white",
          padding: "40px",
          borderRadius: "25px",
          boxShadow: "0 10px 40px rgba(0,0,0,0.3)",
          textAlign: "center",
          width: "380px",
          animation: "fadeIn 1s ease-in-out",
        }}
      >
        <h2 style={{ color: "#ff6f00", marginBottom: "10px" }}>
          🧭 Smart Tourist Safety
        </h2>
        <p style={{ color: "#666", marginBottom: "25px", fontSize: "14px" }}>
          Check if your current area is safe for tourists.
        </p>

        <input
          type="number"
          placeholder="Latitude"
          value={latitude}
          onChange={(e) => setLatitude(e.target.value)}
          style={{
            width: "100%",
            padding: "10px",
            marginBottom: "10px",
            borderRadius: "10px",
            border: "1px solid #ddd",
            textAlign: "center",
          }}
        />
        <input
          type="number"
          placeholder="Longitude"
          value={longitude}
          onChange={(e) => setLongitude(e.target.value)}
          style={{
            width: "100%",
            padding: "10px",
            marginBottom: "20px",
            borderRadius: "10px",
            border: "1px solid #ddd",
            textAlign: "center",
          }}
        />

        <button
          onClick={handleCheckSafety}
          disabled={loading}
          style={{
            width: "100%",
            padding: "12px",
            backgroundColor: "#ff6f00",
            color: "white",
            fontWeight: "bold",
            border: "none",
            borderRadius: "12px",
            cursor: "pointer",
            transition: "background 0.3s ease",
          }}
        >
          {loading ? "Checking..." : "Check Safety 🚦"}
        </button>

        {result && (
          <p
            style={{
              marginTop: "25px",
              fontWeight: "bold",
              color: result.includes("safe") ? "green" : "red",
              fontSize: "16px",
              transition: "color 0.3s ease-in-out",
            }}
          >
            {result}
          </p>
        )}

        {!autoFetched && (
          <p
            style={{
              marginTop: "15px",
              fontSize: "12px",
              color: "#888",
            }}
          >
            📍 Please allow location access for automatic detection
          </p>
        )}
      </div>
    </div>
  );
}
